import{_ as a,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const l="/ascendc.github.io/assets/soa_aos_layout.CBgj92C0.png",k=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/operator_practice"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simt_operator_optimization/memory_access/memory_access"},{"text":"使用SoA布局提升哈希表查找效率","link":"/guide/operator_practice/simt_operator_optimization/memory_access/soa_layout_efficiency"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/memory_access/soa_layout_efficiency.md","filePath":"guide/operator_practice/simt_operator_optimization/memory_access/soa_layout_efficiency.md","lastUpdated":1792747878000}'),t={name:"guide/operator_practice/simt_operator_optimization/memory_access/soa_layout_efficiency.md"};function e(o,s,i,r,_,w){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>使用SoA布局提升哈希表查找效率</h1><p>【优先级】中</p><p>【描述】AoS（Array of Structures，结构体数组）与SoA（Structure of Arrays，数组结构体）为两种不同内存布局：</p><ul><li>AoS布局：每个结构体中包含一个对象的完整信息，多个结构体排列成数组存储在内存中。</li><li>SoA布局：将对象的同种信息排列成数组，多个对象的同种信息存储在相邻内存中。</li></ul><p>【样例介绍】以<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/03_best_practices/00_memory_optimizations/hashtable_lookup">hashtable_lookup样例</a>为例，实现哈希表查找算子，该哈希表处理哈希冲突基于开放寻址法，具体参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/02_features/01_api_features/00_memory_access/insert_hash_table">背景知识</a>，此样例通过不同的哈希表结构设计以及线程访问方式查找哈希表并进行性能比较，展示不同优化手段对性能的影响。</p><p>下图展示了本样例中不同内存布局的哈希表结构。</p><p><strong>图1 内存布局示意图</strong></p><p><img src="'+l+`" alt="内存布局示意图"></p><div data-filter="950"><p>下文性能数据均使用msOpProf工具在Ascend 950PR产品上采集，指标为Task Duration（Task整体耗时，即算子端到端耗时）。</p></div><p>【反例】AoS内存排布场景，8B的key和32B的value连续排布，组成一个Bucket结构，多个Bucket连续排布组成一个数组，查找逻辑逐Bucket读8B key进行比较。每个线程独立负责一条查询key。</p><p>哈希表结构体代码实现如下所示：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">AoSBucket</span><span class="w"> </span><span class="p">{</span>
<span class="w">  </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">key</span><span class="p">;</span>
<span class="w">  </span><span class="kt">float</span><span class="w"> </span><span class="n">value</span><span class="p">[</span><span class="n">DIM</span><span class="p">];</span>
<span class="p">};</span>
<span class="n">AoSBucket</span><span class="w"> </span><span class="n">table</span><span class="p">[</span><span class="n">CAPACITY</span><span class="p">];</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">find_aos</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">AoSBucket</span><span class="o">*</span><span class="w"> </span><span class="n">table</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">target_key</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">start</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">  </span><span class="p">...</span>
<span class="w">  </span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">bucket_key</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">table</span><span class="p">[</span><span class="n">idx</span><span class="p">].</span><span class="n">key</span><span class="p">;</span>
<span class="w">  </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">bucket_key</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">target_key</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">      </span><span class="k">return</span><span class="w"> </span><span class="n">idx</span><span class="p">;</span><span class="w">  </span>
<span class="w">  </span><span class="p">}</span>
<span class="w">  </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">bucket_key</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">EMPTY_KEY</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">      </span><span class="k">return</span><span class="w"> </span><span class="n">NOT_FOUND</span><span class="p">;</span><span class="w">  </span>
<span class="w">  </span><span class="p">}</span>
<span class="w">  </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">idx</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="p">(</span><span class="n">CAPACITY</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span><span class="w">  </span>
<span class="w">  </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><p>上述实现中，每个线程独立负责一条查询key，查找逻辑逐Bucket读8B key进行比较。该实现的性能数据如下：</p><table><thead><tr><th>Case</th><th align="center">Task Duration(μs)</th></tr></thead><tbody><tr><td>0</td><td align="center">1311.297</td></tr></tbody></table><p>【正例】使用SoA布局，key与value分区存储，探测路径与value区解耦，消除value存放在Bucket中对探测访存跨度的干扰。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">SoaTable</span><span class="w"> </span><span class="p">{</span>
<span class="w">  </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">key</span><span class="p">[</span><span class="n">CAPACITY</span><span class="p">];</span>
<span class="w">  </span><span class="kt">float</span><span class="w"> </span><span class="n">value</span><span class="p">[</span><span class="n">CAPACITY</span><span class="p">][</span><span class="n">DIM</span><span class="p">];</span>
<span class="p">};</span>
<span class="n">SoaTable</span><span class="w"> </span><span class="n">table</span><span class="p">;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">find_soa</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">SoaTable</span><span class="o">*</span><span class="w"> </span><span class="n">table</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">target_key</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">start</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">  </span><span class="p">...</span>
<span class="w">  </span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">bucket_key</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">table</span><span class="o">-&gt;</span><span class="n">key</span><span class="p">[</span><span class="n">idx</span><span class="p">];</span>
<span class="w">  </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">bucket_key</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">target_key</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">      </span><span class="k">return</span><span class="w"> </span><span class="n">idx</span><span class="p">;</span><span class="w">  </span>
<span class="w">  </span><span class="p">}</span>
<span class="w">  </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">bucket_key</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">EMPTY_KEY</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">      </span><span class="k">return</span><span class="w"> </span><span class="n">NOT_FOUND</span><span class="p">;</span><span class="w">  </span>
<span class="w">  </span><span class="p">}</span>
<span class="w">  </span><span class="n">idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">idx</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="p">(</span><span class="n">CAPACITY</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span><span class="w">  </span>
<span class="w">  </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><p>算法实现与反例查找算法完全一致。唯一差异是内存布局。SoA布局中所有8MB的key连续存放，所有32MB的value连续存放，key和value分开存储。使用SoA布局后的性能数据如下：</p><table><thead><tr><th>Case</th><th align="center">Task Duration(μs)</th><th align="center">性能对比</th></tr></thead><tbody><tr><td>0</td><td align="center">1311.297</td><td align="center">-</td></tr><tr><td>1</td><td align="center">783.029</td><td align="center">1.67x</td></tr></tbody></table><p>从性能数据可以看出，同一算法，Task Duration从1311.297μs降至783.029μs。SoA布局相对AoS布局提升x1.67。</p><p><strong>优化效果分析</strong>：</p><p>AoS中key和value交替存储，查询key时会将相邻的value一同加载；SoA中所有key连续存储，单条128B Cache Line可容纳更多key，例如16个8B的key，从而减少查找过程中不必要的value数据加载，降低Cache Line搬运开销，提高缓存利用率。</p><p><strong>适用场景扩展</strong></p><p>SoA布局不局限于哈希表查找：当算子存在局部同字段批量访问时，优先考虑SoA而非AoS，将同类字段连续存储，减少无关数据的加载，提高Cache Line利用率，详见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/03_simt_api/03_best_practices/00_memory_optimizations/hashtable_lookup/README.md">哈希表查找性能优化样例</a>。</p><p>【总结】在SIMT编程中，使用SoA的内存布局时同类字段连续存储，针对高频访问局部数据的场景，SoA的内存排布可显著提高Cache Line利用率，从而提升整体性能。</p></article></div>`,1)])])}const u=a(t,[["render",e]]);export{k as __pageData,u as default};
